import hashlib,json,os,re,statistics,subprocess,tempfile,time
from pathlib import Path
os.sched_setaffinity(0,{0})
binaries={'parent':'build/review-j07/release/mus-solver','accepted':'build/review-j01/release/mus-solver','final':'build/review-j01-final/release/mus-solver'}
data={'method':'Three paired runs, alternating order, CPU0, seed7 and one thread. No own concurrent builds or tests. Public format compared with the accepted candidate; historical formats and score compared with HEAD83c0a28.','binary_sha256':{k:hashlib.sha256(Path(v).read_bytes()).hexdigest() for k,v in binaries.items()},'runs':[],'summary':[],'checkpoint_checks':[]}
out=Path('/tmp/mus-review-j01-final-performance.json')
def save():out.write_text(json.dumps(data,indent=2)+'\n')
def run(group,version,args,repeat):
 command=[binaries[version],*args]
 with tempfile.TemporaryFile(mode='w+') as log:
  start=time.perf_counter();pid=os.posix_spawn(command[0],command,os.environ,file_actions=[(os.POSIX_SPAWN_DUP2,log.fileno(),1),(os.POSIX_SPAWN_DUP2,log.fileno(),2)])
  _,status,usage=os.wait4(pid,0);elapsed=time.perf_counter()-start;log.seek(0);stdout=log.read()
 if status:raise RuntimeError((command,status,stdout))
 row={'group':group,'version':version,'repeat':repeat,'command':command,'wall_seconds':elapsed,'peak_rss_kib':usage.ru_maxrss,'stdout':stdout}
 if group!='score':
  for k,v in re.findall(r'(\w+)=([\d.]+)',stdout):row['training_seconds' if k=='seconds' else k]=float(v) if '.' in v else int(v)
 data['runs'].append(row);save();print(json.dumps(row),flush=True)
 return row
def summary(group,before):
 rows=[r for r in data['runs'] if r['group']==group];s={'group':group,'before':before,'after':'final'}
 for metric in ['wall_seconds','peak_rss_kib']+([] if group=='score' else ['training_seconds','visited_nodes','information_sets']):
  a=statistics.median(r[metric] for r in rows if r['version']==before);b=statistics.median(r[metric] for r in rows if r['version']=='final');s[metric]={'before':a,'after':b,'change_percent':100*(b/a-1)}
 data['summary'].append(s);save();print('SUMMARY '+json.dumps(s),flush=True)
 if s['wall_seconds']['change_percent']>=20 or s['peak_rss_kib']['change_percent']>=25:raise RuntimeError('Additional performance concern; confirmation required')
for fmt,it in [('single-bet',100000),('raises-to-eight',30000),('ordago',500),('ordago-public',500)]:
 before='accepted' if fmt=='ordago-public' else 'parent'
 for repeat in range(3):
  for version in ([before,'final'] if repeat%2==0 else ['final',before]):run(fmt,version,['--format',fmt,'--iterations',str(it),'--seed','7','--threads','1'],repeat+1)
 summary(fmt,before)
# Small deterministic checkpoints test serialized keys, policy and counters.
for fmt,it in [('single-bet',1000),('raises-to-eight',500),('ordago',20),('ordago-public',20)]:
 before='accepted' if fmt=='ordago-public' else 'parent'
 with tempfile.TemporaryDirectory(prefix='mus-review-j01-checkpoint-') as directory:
  hashes={}
  for version in [before,'final']:
   path=Path(directory)/f'{version}.cfr'
   command=[binaries[version],'--format',fmt,'--iterations',str(it),'--seed','7','--save',str(path)]
   result=subprocess.run(command,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,check=True)
   hashes[version]=hashlib.sha256(path.read_bytes()).hexdigest()
  assert len(set(hashes.values()))==1,(fmt,hashes)
  data['checkpoint_checks'].append({'format':fmt,'iterations':it,'before':before,'sha256':hashes,'files_identical':True});save()
# Full v4 tables must preserve every published checkpoint and value file.
reference=None
for repeat in range(3):
 for version in (['parent','final'] if repeat%2==0 else ['final','parent']):
  with tempfile.TemporaryDirectory(prefix='mus-review-j01-score-') as directory:
   path=Path(directory)/'table'
   row=run('score',version,['--format','ordago-score','--score','35:35','--continuation',str(path),'--iterations','1000','--evaluation-samples','10000','--seed','7','--threads','1'],repeat+1)
   hashes={p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(path.iterdir()) if p.is_file()}
   assert len(hashes)==46,len(hashes)
   if reference is None:reference=hashes
   assert hashes==reference,(version,repeat)
   row['files_identical']=True;row['file_sha256']=hashes;save()
summary('score','parent')
print('ALL_CHECKS_PASSED',flush=True)

legacy_reference.probe_source:
#include <stdint.h>
#include <inttypes.h>
#include <stdio.h>
#include <stdlib.h>
#include "mus_solver/mus_game.h"
#define CHECK(c) do { if (!(c)) { fprintf(stderr,"line %d: %s\n",__LINE__,#c); exit(1); } } while(0)
static GameState *as_game(MusGameState *s) { return mus_game_state_as_game_state(s); }
static uint64_t digest_value(uint64_t hash, uint64_t value) {
    for (int byte = 0; byte < 8; ++byte) {
        hash = (hash ^ (value & UINT64_C(255))) * UINT64_C(1099511628211);
        value >>= 8;
    }
    return hash;
}

/* Explicit byte order avoids compiler padding and host-endian dependencies. */
static uint64_t legacy_playout_digest(unsigned int format) {
    const Game *game = format == 0 ? mus_single_bet_game_descriptor()
                       : format == 1 ? mus_raises_to_eight_game_descriptor()
                                     : mus_ordago_game_descriptor();
    uint64_t hash = UINT64_C(14695981039346656037);
    uint32_t random = 7;
    for (unsigned int sample = 0; sample < 256; ++sample) {
        MusGameState state;
        CHECK((format == 0 ? mus_single_bet_game_state_init(&state)
               : format == 1 ? mus_raises_to_eight_game_state_init(&state)
                             : mus_ordago_game_state_init(&state)) == CFR_STATUS_SUCCESS);
        size_t steps = 0;
        while (state.model.phase != MUS_PHASE_TERMINAL) {
            CHECK(++steps < 150);
            Actor actor;
            CHECK(cfr_game_current_actor(game, as_game(&state), &actor) == CFR_STATUS_SUCCESS);
            Action actions[MUS_GAME_MAX_LEGAL_ACTIONS];
            size_t count;
            CHECK(cfr_game_legal_actions(game, as_game(&state), actions,
                  MUS_GAME_MAX_LEGAL_ACTIONS, &count) == CFR_STATUS_SUCCESS);
            hash = digest_value(hash, state.model.phase);
            hash = digest_value(hash, count);
            for (size_t i = 0; i < count; ++i) hash = digest_value(hash, (uint64_t)actions[i]);
            if (actor.kind == CFR_ACTOR_PLAYER) {
                InfoSetKey key;
                CHECK(cfr_game_information_set_key(game, as_game(&state), &key) == CFR_STATUS_SUCCESS);
                hash = digest_value(hash, (uint64_t)key);
            }
            random = random * UINT32_C(1664525) + UINT32_C(1013904223);
            size_t choices = count;
            if ((sample & 1U) != 0 && count > 1 && actions[count - 1] == MUS_ACTION_ORDAGO)
                --choices;
            CHECK(cfr_game_apply_action(game, as_game(&state), actions[random % choices]) == CFR_STATUS_SUCCESS);
        }
        Utility value;
        CHECK(cfr_game_terminal_utility(game, as_game(&state), CFR_PLAYER_0, &value) == CFR_STATUS_SUCCESS);
        CHECK(value >= -40 && value <= 40);
        hash = digest_value(hash, (uint64_t)(value + 40));
    }
    return hash;
}

int main(void) { for(unsigned int f=0;f<3;f++)printf("muses=%d format=%u digest=%016" PRIx64 "\n",MUS_GAME_MAX_MUSES,f,legacy_playout_digest(f)); }
